{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a behavioral response (HTTP 401) to a specific input (missing token) that can be observed by executing the system."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Role-based access control and the resulting HTTP 403 response are functional behaviors that can be verified by sending requests with different roles."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Rate limiting behavior, including the HTTP 429 status and Retry-After header, can be verified by sending a burst of requests exceeding the limit."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Verifying latency at the 99th percentile under a specific load requires statistical analysis of performance data collected during a load test."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "The timeout behavior and HTTP 504 response can be observed by simulating a slow backend service and checking the gateway's reaction."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to apply configuration changes without restart or request loss is a dynamic behavior that can be verified by changing config during active traffic."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "The content of the log entries can be verified by sending requests and inspecting the generated log files for the required fields."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Monthly availability is a statistical metric that requires analysis of uptime data over a period, not a single functional test."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that all specified fields are captured."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Testing confirms the presence of the four categories, while inspection verifies that each category is displayed with a distinct colour as required."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by inputting vital signs within and outside the defined ranges to observe correct recording and rejection behaviour."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The application is tested in an offline environment to confirm full functionality and the ability to store at least 500 records locally."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The synchronization and conflict resolution logic is verified by simulating connectivity restoration and conflicting edits to observe the retention of both versions."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The use of AES-256 encryption is verified by inspecting the code or configuration to confirm the specified algorithm is implemented for data storage."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operability with surgical gloves is demonstrated by a user performing standard interactions on the tablet without removing the gloves."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Battery endurance is verified through analysis of power consumption models or simulation under the defined usage profile to ensure the 8-hour requirement is met."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior of classifying documents into one of 12 categories and returning a confidence score between 0 and 1 is verified by executing the service with sample inputs and observing the output."
    },
    {
      "requirement_id": "AI-002",
      "methods": [
        "Analiz"
      ],
      "rationale": "Achieving a specific macro-averaged F1 score on a held-out evaluation set requires statistical analysis of the model's performance metrics."
    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing logic for low-confidence documents is verified by submitting documents with confidence scores below 0.60 and observing if they are directed to the human review queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under load is verified by executing a load test at 50 requests per second and measuring the response times to ensure the 95th percentile is within 500 ms."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "Test"
      ],
      "rationale": "The logging functionality is verified by sending requests and checking the system logs or database to confirm that the model version, input hash, and predicted category are recorded."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting deviation in the weekly distribution of predicted categories using the population stability index requires statistical analysis of the data over time."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The provision of the three most contributing text passages is verified by executing a classification request and inspecting the response payload for the required passages."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall rates between Turkish and English documents to ensure the difference is within 5 percentage points requires statistical analysis of the model's performance on separate language subsets."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresinin doğrulanması için sisteme girdi verilerek harita üzerindeki görsel çıktı ve zamanlama gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi yapılarak 2.000 iz altında ekran yenileme hızının ölçülmesi ve gözlemlenmesi gerekmektedir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Test"
      ],
      "rationale": "Operatörün iz seçimi işlemi gerçekleştirilerek ekranda doğru bilgilerin görüntülenip görüntülenmediği gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Güncelleme akışının durdurulmasıyla zamanlama senaryolarının çalıştırılması ve iz durumlarının gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği sistemin çalıştırılmasıyla gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderim işlemi yapılarak iletim süresinin ölçülmesi ve durum bildirimlerinin ekranda gözlemlenmesi gerekmektedir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Kayıt işleminin çalıştığı test edilerek log dosyalarının içeriği ve değiştirilemezlik mekanizmasının yapılandırması incelenmelidir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucunun durdurulması senaryosu çalıştırılarak devralma süresinin ölçülmesi ve veri bütünlüğünün doğrulanması gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı girişi yapılarak gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık bekleme süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışı, zamanlayıcı testleri ile sistemin çalıştırılması üzerinden doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık süre, sisteme girdi verilerek ve sonuç gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti ve adet sınırı kısıtlarının uygulanıp uygulanmadığı, farklı senaryolarda dosya yüklenerek sistemin tepkisi gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanması sonrası benzersiz numara üretimi ve e-posta gönderimi, işlem gerçekleştirilip çıktıların kontrol edilmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde devam etme işlevi, sistemin çalıştırılarak veri girişinin durdurulması ve yeniden erişim sağlanması ile doğrulanabilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, kullanıcı arayüzü kodunun ve yapılandırmasının standartlara göre gözle denetlenerek (inceleme) doğrulanır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma belgeleri ve sunucu konum ayarlarının gözle denetlenmesiyle doğrulanır."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Macro-averaged F1 score verification on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. A held-out evaluation dataset is available and accessible.",
      "test_inputs": "Held-out evaluation dataset containing labeled documents.",
      "assumptions": "The evaluation script correctly calculates the macro-averaged F1 score.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation process on the held-out evaluation set using the trained model.",
          "expected": "The system completes the evaluation without errors."
        },
        {
          "no": 2,
          "action": "Retrieve the calculated macro-averaged F1 score from the evaluation results.",
          "expected": "The reported macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. A held-out evaluation dataset containing both Turkish and English documents is available.",
      "test_inputs": "Held-out evaluation dataset with labeled Turkish and English documents.",
      "assumptions": "The evaluation script correctly calculates recall separately for Turkish and English document subsets.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation process on the held-out evaluation set, filtering results by language (Turkish and English).",
          "expected": "The system completes the evaluation and provides separate recall metrics for Turkish and English documents."
        },
        {
          "no": 2,
          "action": "Calculate the absolute difference between the recall score for Turkish documents and the recall score for English documents.",
          "expected": "The absolute difference in recall is less than or equal to 5 percentage points (0.05)."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and running on the tablet. A test casualty record has been created and saved.",
      "test_inputs": "A sample casualty record with unique identifiers (e.g., Name: 'Test Patient', ID: '12345').",
      "assumptions": "Access to the device's file system or storage dump is available for inspection.",
      "steps": [
        {
          "no": 1,
          "action": "Create and save a new casualty record in the application.",
          "expected": "The record is successfully saved and visible in the application interface."
        },
        {
          "no": 2,
          "action": "Access the underlying storage file or database where the casualty data is persisted.",
          "expected": "The raw data is not readable as plain text; it appears as encrypted binary data."
        },
        {
          "no": 3,
          "action": "Verify the encryption algorithm used for the stored data using a forensic tool or configuration check.",
          "expected": "The encryption method is confirmed to be AES-256."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Battery life under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100%). The 'defined usage profile' is documented and available (e.g., continuous screen on, GPS active, specific app interactions).",
      "test_inputs": "None (continuous operation).",
      "assumptions": "The 'defined usage profile' is a standardized script or set of actions that simulates typical field triage usage (e.g., screen brightness at 50%, periodic data entry, GPS enabled).",
      "steps": [
        {
          "no": 1,
          "action": "Start the tablet with a full battery and begin executing the defined usage profile continuously.",
          "expected": "The tablet operates normally, and the battery level starts decreasing."
        },
        {
          "no": 2,
          "action": "Monitor the tablet's operation and battery level until the battery is depleted or the device shuts down.",
          "expected": "The tablet remains operational for at least 8 hours before the battery is depleted or the device shuts down."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Kullanıcı arayüzünün WCAG 2.1 AA uyumluluğunun doğrulanması",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Sistem test ortamında çalışmaktadır ve tarayıcıda erişilebilirlik eklentileri (ör. Lighthouse, axe-core) yüklüdür.",
      "test_inputs": "Portalın ana sayfası ve temel işlevsellik sayfaları (giriş, başvuru formu).",
      "assumptions": "WCAG 2.1 AA kriterleri için otomatik test araçlarının %100 doğruluk sağlamadığı, ancak temel yapısal hataları yakalayabildiği kabul edilir.",
      "steps": [
        {
          "no": 1,
          "action": "Tarayıcıda erişilebilirlik denetimi eklentisi (ör. Lighthouse) kullanılarak portalın ana sayfası taranır.",
          "expected": "Rapor, WCAG 2.1 AA kriterleri için kritik hata (critical) veya yüksek öncelikli (serious) sorun içermemeli; erişilebilirlik skoru 90 ve üzeri olmalıdır."
        },
        {
          "no": 2,
          "action": "Klavye navigasyonu kullanılarak sayfadaki tüm etkileşimli öğelere (butonlar, giriş alanları, menüler) sırayla erişilir.",
          "expected": "Tüm etkileşimli öğeler klavye ile odaklanabilir ve kullanılabilir olmalı; odak göstergesi (focus indicator) görünür olmalıdır."
        },
        {
          "no": 3,
          "action": "Ekran okuyucu (ör. NVDA veya JAWS) etkinleştirilerek sayfa içeriği dinlenir.",
          "expected": "Başlıklar, form alanları ve butonlar doğru etiketlerle ve mantıksal sırayla okunmalıdır; görsel içerikler için alternatif metin (alt text) sağlanmalıdır."
        }
      ]
    }
  ]
}

