{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Offline functionality and local storage capacity",
      "covers": [
        "MED-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and configured. Network connectivity is disabled (airplane mode or disconnected).",
      "test_inputs": "500 unique casualty record data sets.",
      "assumptions": "The application allows manual creation of casualty records. The 'fully functional' scope includes creating, viewing, and editing records.",
      "steps": [
